{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None), event("b", 1, False)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_not_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 1, False)] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days,expected", [(0, 0), (1, 3), (2, 5), (3, 6), (8, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_fields_and_skipped_lines():
    lines = [" \n", "  # comment, even, with commas\n", " a , -2 , 1 \n",
             "b, 0, 0", "c, 3,  "]
    assert parse_transcript_log(lines) == [event("a", -2, True),
                                           event("b", 0, False),
                                           event("c", 3, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1,true"])
def test_parse_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_transcript_log(["", " # skipped", bad_line])


def test_dedupe_keeps_last_duplicate_id_and_sorts_by_day_then_id():
    events = [event("b", 1, True), event("a", 2, True),
              event("b", 3, False), event("c", 2, None),
              event("a", 2, False)]
    assert dedupe_transcripts(events) == [events[4], events[3], events[2]]
    assert dedupe_transcripts([]) == []


def test_daily_counts_fill_range_and_ignore_outside():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, False), event("e", 2, None), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 3, True), event("c", 4, False)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary(groups, 20)["recent"] == 2
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "a": [event("a", 1, True)], "b": [event("b", 1, False)]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_sorted_with_none_for_empty():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    rates = flag_rate_by_group(groups)
    assert list(rates.items()) == [("a", 1.0), ("b", 0.0), ("z", None)]
    assert flag_rate_by_group({}) == {}


def test_longest_streak_requires_consecutive_positive_entries():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([0, -2, 0]) == 0
    assert longest_flag_streak([]) == 0
